pub fn ordered_pool(kind: LessonKind, top: usize) -> Vec<&'static str> {
    let top = top.min(200);
    let mut out = Vec::with_capacity(top);
    match kind {
        LessonKind::Bigrams => extend_bins(
            &mut out,
            top,
            &BIGRAMS_TOP_10,
            &BIGRAMS_11_20,
            &BIGRAMS_21_30,
            &BIGRAMS_31_40,
            &BIGRAMS_41_50,
            &BIGRAMS_51_200,
        ),
        LessonKind::Trigrams => extend_bins(
            &mut out,
            top,
            &TRIGRAMS_TOP_10,
            &TRIGRAMS_11_20,
            &TRIGRAMS_21_30,
            &TRIGRAMS_31_40,
            &TRIGRAMS_41_50,
            &TRIGRAMS_51_200,
        ),
        LessonKind::Tetragrams => extend_bins(
            &mut out,
            top,
            &TETRAGRAMS_TOP_10,
            &TETRAGRAMS_11_20,
            &TETRAGRAMS_21_30,
            &TETRAGRAMS_31_40,
            &TETRAGRAMS_41_50,
            &TETRAGRAMS_51_200,
        ),
        LessonKind::Words => extend_bins(
            &mut out,
            top,
            &WORDS_TOP_10,
            &WORDS_11_20,
            &WORDS_21_30,
            &WORDS_31_40,
            &WORDS_41_50,
            &WORDS_51_200,
        ),
    }
    out
}

fn extend_bins(
    out: &mut Vec<&'static str>,
    top: usize,
    top_10: &[&'static str],
    mid_20: &[&'static str],
    mid_30: &[&'static str],
    mid_40: &[&'static str],
    mid_50: &[&'static str],
    rest: &[&'static str],
) {
    let bins: [&[&'static str]; 6] = [top_10, mid_20, mid_30, mid_40, mid_50, rest];
    for bin in bins {
        if out.len() >= top {
            break;
        }
        let remaining = top - out.len();
        out.extend(bin.iter().take(remaining).copied());
    }
}

pub fn parse_layout(name: &str) -> LayoutId {
    match name {
        "qwertz" => LayoutId::Qwertz,
        "azerty" => LayoutId::Azerty,
        "dvorak" => LayoutId::Dvorak,
        "colemak" => LayoutId::Colemak,
        "colemakdh" => LayoutId::ColemakDh,
        _ => LayoutId::Qwerty,
    }
}

pub fn layout_def(layout: LayoutId) -> LayoutDef {
    match layout {
        LayoutId::Qwerty => LayoutDef {
            top: ["q", "w", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]"],
            home: ["a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'"],
            bottom: ["z", "x", "c", "v", "b", "n", "m", ",", ".", "/"],
        },
        LayoutId::Qwertz => LayoutDef {
            top: ["q", "w", "e", "r", "t", "z", "u", "i", "o", "p", "ü", "+"],
            home: ["a", "s", "d", "f", "g", "h", "j", "k", "l", "ö", "ä"],
            bottom: ["y", "x", "c", "v", "b", "n", "m", ",", ".", "-"],
        },
        LayoutId::Azerty => LayoutDef {
            top: ["a", "z", "e", "r", "t", "y", "u", "i", "o", "p", "^", "$"],
            home: ["q", "s", "d", "f", "g", "h", "j", "k", "l", "m", "ù"],
            bottom: ["w", "x", "c", "v", "b", "n", ",", ";", ":", "!"],
        },
        LayoutId::Dvorak => LayoutDef {
            top: ["'", ",", ".", "p", "y", "f", "g", "c", "r", "l", "/", "="],
            home: ["a", "o", "e", "u", "i", "d", "h", "t", "n", "s", "-"],
            bottom: [";", "q", "j", "k", "x", "b", "m", "w", "v", "z"],
        },
        LayoutId::Colemak => LayoutDef {
            top: ["q", "w", "f", "p", "g", "j", "l", "u", "y", ";", "[", "]"],
            home: ["a", "r", "s", "t", "d", "h", "n", "e", "i", "o", "'"],
            bottom: ["z", "x", "c", "v", "b", "k", "m", ",", ".", "/"],
        },
        LayoutId::ColemakDh => LayoutDef {
            top: ["q", "w", "f", "p", "b", "j", "l", "u", "y", ";", "[", "]"],
            home: ["a", "r", "s", "t", "g", "m", "n", "e", "i", "o", "'"],
            bottom: ["z", "x", "c", "d", "v", "k", "h", ",", ".", "/"],
