+        help = "your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."
+    )]
+    emu_in: String,
+
+    #[arg(
+        long = "emu-out",
+        default_value = "",
+        value_name = "layout",
+        help = "the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."
+    )]
+    emu_out: String,
+
+    #[arg(long = "show-ortho", help = "show keyboard in ortholinear format")]
+    show_ortho: bool,
+
+    #[arg(long = "nokb", help = "pass this flag to disable the keyboard layout display.")]
+    nokb: bool,
+
+    #[arg(long = "cat", help = "the most important flag. don't practice alone.")]
+    cat: bool,
+}
+
+#[derive(Clone, Debug)]
+struct Config {
+    top: usize,
+    combi: usize,
+    rep: usize,
+    wpm_target: u64,
+    acc_target: u64,
+    show_ortho: bool,
+    nokb: bool,
+    cat: bool,
+    emu: Option<(LayoutId, LayoutId)>,
+    keyboard_layout: LayoutId,
+}
+
+#[derive(Clone, Debug)]
+enum PoolSource {
+    Builtin(LessonKind),
+    File(Vec<String>),
+}
+
+#[derive(Clone, Debug)]
+struct LessonState {
+    expected: Vec<char>,
+    cursor: usize,
+    mismatches: Vec<Option<char>>,
+    space_mismatches: Vec<bool>,
+    had_mistake: bool,
+    locked: bool,
+    started_at: Option<Instant>,
+}
+
+impl LessonState {
+    fn new(text: String) -> Self {
+        let expected: Vec<char> = text.chars().collect();
+        let len = expected.len();
+        Self {
+            expected,
+            cursor: 0,
+            mismatches: vec![None; len],
+            space_mismatches: vec![false; len],
+            had_mistake: false,
+            locked: false,
+            started_at: None,
+        }
+    }
+}
+
+struct App {
+    config: Config,
+    pool: Vec<String>,
+    rng: ThreadRng,
+    lesson_number: u64,
+    success_count: u64,
+    fail_count: u64,
+    finished_lessons: u64,
+    total_wpm: u64,
+    total_acc: u64,
+    last_wpm: u64,
+    last_acc: u64,
+    lesson: LessonState,
+}
+
+impl App {
+    fn new(config: Config, source: PoolSource) -> Self {
+        let pool = match source {
+            PoolSource::Builtin(kind) => ordered_pool(kind, config.top)
+                .into_iter()
+                .map(str::to_string)
+                .collect(),
+            PoolSource::File(words) => words,
+        };
+
+        let mut app = Self {
+            config,
+            pool,
+            rng: rand::thread_rng(),
+            lesson_number: 1,
+            success_count: 0,
+            fail_count: 0,
+            finished_lessons: 0,
+            total_wpm: 0,
+            total_acc: 0,
+            last_wpm: 0,
+            last_acc: 0,
+            lesson: LessonState::new(String::new()),
+        };
+        app.start_next_lesson();
+        app
+    }
+
+    fn start_next_lesson(&mut self) {
+        if self.pool.is_empty() {
+            panic_like_empty_pool();
+        }
+
+        let mut picked = Vec::with_capacity(self.config.combi);
+        for _ in 0..self.config.combi {
+            let word = self.pool.choose(&mut self.rng).cloned().unwrap();
+            picked.push(word);
+        }
+
+        let mut lesson = String::new();
+        for _ in 0..self.config.rep {
+            for token in &picked {
+                lesson.push_str(token);
+                lesson.push(' ');
+            }
+        }
+
+        self.lesson = LessonState::new(lesson);
+    }
+
+    fn avg_wpm(&self) -> u64 {
+        if self.finished_lessons == 0 {
+            0
+        } else {
+            self.total_wpm / self.finished_lessons
+        }
+    }
+
+    fn avg_acc(&self) -> u64 {
+        if self.finished_lessons == 0 {
+            0
+        } else {
+            self.total_acc / self.finished_lessons
+        }
+    }
+
+    fn map_input_char(&self, ch: char) -> char {
+        if ch == ' ' {
+            return ' ';
+        }
+
+        let Some((input, output)) = self.config.emu else {
+            return ch;
+        };
+
+        remap_char(ch, input, output)
+    }
+
+    fn push_char(&mut self, ch: char) {
+        if self.lesson.locked || self.lesson.cursor >= self.lesson.expected.len() {
+            return;
+        }
+
+        if self.lesson.started_at.is_none() {
+            self.lesson.started_at = Some(Instant::now());
+        }
+
+        let pos = self.lesson.cursor;
+        let expected = self.lesson.expected[pos];
+        let mapped = self.map_input_char(ch);
+
+        if mapped != expected {
+            self.lesson.had_mistake = true;
+            if expected == ' ' {
+                self.lesson.space_mismatches[pos] = true;
+            }
+            if mapped != ' ' {
+                self.lesson.mismatches[pos] = Some(mapped);
+            }
+        }
+
+        self.lesson.cursor += 1;
+        if self.lesson.cursor == self.lesson.expected.len() {
+            if self.lesson.had_mistake {
+                self.lesson.locked = true;
+            } else {
+                self.finish_lesson();
+            }
+        }
+    }
+
+    fn finish_lesson(&mut self) {
+        let non_space = self
+            .lesson
+            .expected
+            .iter()
+            .filter(|&&ch| ch != ' ')
+            .count() as f64;
+
+        let elapsed = self
+            .lesson
+            .started_at
+            .map(|started| started.elapsed().as_secs_f64())
+            .unwrap_or(0.0);
+
+        let wpm = if non_space == 0.0 || elapsed <= 0.0 {
+            0
+        } else {
+            (((non_space / 5.0) * 60.0) / elapsed).round() as u64
+        };
+        let acc = 100u64;
+
+        self.last_wpm = wpm;
+        self.last_acc = acc;
+        self.total_wpm += wpm;
+        self.total_acc += acc;
+        self.finished_lessons += 1;
+
+        if wpm >= self.config.wpm_target && acc >= self.config.acc_target {
+            self.success_count += 1;
+        } else {
+            self.fail_count += 1;
+        }
+
+        self.lesson_number += 1;
+        self.start_next_lesson();
+    }
+}
+
+fn main() {
+    let cli = Cli::parse();
+
+    validate_range("top", cli.top, 1, 200);
+    validate_range("combi", cli.combi, 1, 200);
+    validate_range("rep", cli.rep, 1, 200);
+    validate_range("wpm", cli.wpm, 1, 200);
+    validate_range("acc", cli.acc, 0, 100);
+
+    let emu = match (!cli.emu_in.is_empty(), !cli.emu_out.is_empty()) {
+        (false, false) => None,
+        (true, true) => Some((parse_layout(&cli.emu_in), parse_layout(&cli.emu_out))),
+        _ => {
+            eprintln!("You need to specify both emu_in and emu_out.");
+            process::exit(1);
+        }
+    };
+
+    let keyboard_layout = emu.map(|(_, out)| out).unwrap_or(LayoutId::Qwerty);
+    let config = Config {
+        top: cli.top as usize,
+        combi: cli.combi as usize,
+        rep: cli.rep as usize,
+        wpm_target: cli.wpm as u64,
+        acc_target: cli.acc as u64,
+        show_ortho: cli.show_ortho,
+        nokb: cli.nokb,
+        cat: cli.cat,
+        emu,
+        keyboard_layout,
+    };
+
+    let source = match cli.n.as_str() {
+        "2" => PoolSource::Builtin(LessonKind::Bigrams),
+        "3" => PoolSource::Builtin(LessonKind::Trigrams),
+        "4" => PoolSource::Builtin(LessonKind::Tetragrams),
+        "w" => PoolSource::Builtin(LessonKind::Words),
+        path => {
+            let raw = match fs::read_to_string(path) {
+                Ok(text) => text,
+                Err(_) => {
+                    eprintln!("File not found: {path}");
+                    process::exit(1);
+                }
+            };
+            let words = raw
+                .split(',')
+                .filter(|part| !part.is_empty())
+                .map(|part| part.to_string())
+                .collect::<Vec<_>>();
+            PoolSource::File(words)
+        }
+    };
+
+    let mut app = App::new(config, source);
+    if let Err(err) = run(&mut app) {
+        let _ = disable_raw_mode();
+        let _ = crossterm::execute!(io::stdout(), LeaveAlternateScreen);
+        eprintln!("{err}");
+        process::exit(1);
+    }
+}
+
+fn run(app: &mut App) -> io::Result<()> {
+    enable_raw_mode()?;
+    let mut stdout = io::stdout();
+    crossterm::execute!(stdout, EnterAlternateScreen, Clear(ClearType::All))?;
+
+    loop {
+        render(&mut stdout, app)?;
+        stdout.flush()?;
+
+        let Event::Key(key) = event::read()? else {
+            continue;
+        };
+        if key.kind != KeyEventKind::Press {
+            continue;
+        }
+
+        match key.code {
+            KeyCode::Esc => break,
+            KeyCode::Char(ch) => app.push_char(ch),
+            _ => {}
+        }
+    }
+
+    disable_raw_mode()?;
+    crossterm::execute!(stdout, LeaveAlternateScreen)?;
+    Ok(())
+}
+
+fn validate_range(name: &str, value: u16, min: u16, max: u16) {
+    if value < min || value > max {
+        eprintln!("Invalid argument for {name}. Use a number between {min} and {max}.");
+        process::exit(1);
+    }
+}
+
+fn panic_like_empty_pool() -> ! {
+    eprintln!();
+    eprintln!(
+        "thread 'main' ({}) panicked at src/game.rs:18:45:",
+        process::id()
+    );
+    eprintln!("called `Option::unwrap()` on a `None` value");
+    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
+    process::exit(101);
+}
+
+fn remap_char(ch: char, input: LayoutId, output: LayoutId) -> char {
+    if let Some(mapped) = remap_exact(ch, input, output) {
+        return mapped;
+    }
+
+    if ch.is_ascii_uppercase() {
+        let lower = ch.to_ascii_lowercase();
+        if let Some(mapped) = remap_exact(lower, input, output) {
+            return mapped.to_ascii_uppercase();
+        }
+    }
+
+    ch
+}
+
+fn remap_exact(ch: char, input: LayoutId, output: LayoutId) -> Option<char> {
+    let input_layout = layout_def(input);
+    let output_layout = layout_def(output);
+    for (in_row, out_row) in [
+        (&input_layout.top[..], &output_layout.top[..]),
+        (&input_layout.home[..], &output_layout.home[..]),
+        (&input_layout.bottom[..], &output_layout.bottom[..]),
+    ] {
+        for (from, to) in in_row.iter().zip(out_row.iter()) {
+            let mut from_chars = from.chars();
+            let from_char = from_chars.next()?;
+            if from_char == ch {
+                return to.chars().next();
+            }
+        }
+    }
+    None
+}
+
+fn render(stdout: &mut Stdout, app: &App) -> io::Result<()> {
+    let height = if app.config.nokb { 13 } else { 19 };
+    let mut grid = vec![vec![' '; FRAME_WIDTH]; height];
+
+    draw_top_border(&mut grid);
+    if app.config.nokb {
+        draw_nokb_body(&mut grid, app);
+    } else {
+        draw_keyboard_body(&mut grid, app);
+    }
+
+    queue!(stdout, MoveTo(0, 0), Clear(ClearType::All))?;
+    for (row_idx, row) in grid.iter().enumerate() {
+        let line: String = row.iter().collect();
+        queue!(
+            stdout,
+            MoveTo(0, row_idx as u16),
+            SetAttribute(Attribute::Reset),
+            Print(line)
+        )?;
+    }
+
+    draw_title_overlay(stdout)?;
+    draw_prompt_overlay(stdout, app)?;
+    queue!(stdout, SetAttribute(Attribute::Reset))?;
+    Ok(())
+}
+
+fn draw_top_border(grid: &mut [Vec<char>]) {
+    put_text(grid, 0, 0, "╭");
+    put_text(grid, 0, FRAME_WIDTH - 1, "╮");
+    for x in 1..(FRAME_WIDTH - 1) {
+        put_text(grid, 0, x, "─");
+    }
+    put_text(grid, 0, 66, " Quit <esc> ");
+}
+
+fn draw_nokb_body(grid: &mut [Vec<char>], app: &App) {
+    draw_framed_content(grid, 1, 11);
+    put_divider(grid, 2);
+    put_divider(grid, 4);
+    put_divider(grid, 9);
+    draw_bottom_border(grid, 12);
+    draw_shared_content(grid, app, 3, 6, 7, 10, 11);
+
+    if app.config.cat {
+        put_text(grid, 10, 63, "/\\_/\\\\");
+        put_text(grid, 11, 62, ">(•༝• )<");
+        put_text(grid, 12, 57, "────────────────────────────────────────────────────────────    |    \\───────");
+    }
+}
+
+fn draw_keyboard_body(grid: &mut [Vec<char>], app: &App) {
+    draw_framed_content(grid, 1, 17);
+    put_divider(grid, 2);
+    put_divider(grid, 4);
+    put_divider(grid, 15);
+    draw_bottom_border(grid, 18);
+    draw_shared_content(grid, app, 3, 6, 7, 16, 17);
+
+    let layout = layout_def(app.config.keyboard_layout);
+    let lines = if app.config.show_ortho {
+        ortholinear_keyboard_lines(layout)
+    } else {
+        standard_keyboard_lines(layout)
+    };
+    let keyboard_x = if app.config.cat {
+        5
+    } else {
+        centered_x(&lines[0], CONTENT_WIDTH) + 1
+    };
+
+    for (idx, line) in lines.iter().enumerate() {
+        put_text(grid, 8 + idx, keyboard_x, line);
+    }
+
+    if app.config.cat {
+        put_text(grid, 10, 65, "/\\_/\\\\");
+        put_text(grid, 11, 63, ">(•༝• )<");
+        put_text(grid, 12, 64, "|    \\");
+        put_text(grid, 13, 64, "|| |  )");
+        put_text(grid, 14, 64, "ll-l-//");
+        put_text(grid, 15, 1, "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───");
+        put_text(grid, 16, 69, "\\\\");
+        put_text(grid, 17, 69, "V");
+    }
+}
+
+fn draw_framed_content(grid: &mut [Vec<char>], start_row: usize, end_row: usize) {
+    for row in start_row..end_row {
+        put_text(grid, row, 0, "│");
+        put_text(grid, row, FRAME_WIDTH - 1, "│");
+    }
+}
+
+fn put_divider(grid: &mut [Vec<char>], row: usize) {
+    put_text(grid, row, 0, "│");
+    put_text(grid, row, FRAME_WIDTH - 1, "│");
+    for x in 1..(FRAME_WIDTH - 1) {
+        put_text(grid, row, x, "─");
+    }
+}
+
+fn draw_bottom_border(grid: &mut [Vec<char>], row: usize) {
+    put_text(grid, row, 0, "╰");
+    put_text(grid, row, FRAME_WIDTH - 1, "╯");
+    for x in 1..(FRAME_WIDTH - 1) {
+        put_text(grid, row, x, "─");
+    }
+}
+
+fn draw_shared_content(
+    grid: &mut [Vec<char>],
+    app: &App,
+    header_row: usize,
+    prompt_row: usize,
+    mismatch_row: usize,
+    wpm_row: usize,
+    acc_row: usize,
+) {
+    let title = "ngrrram!   by winterveil";
+    let title_x = centered_x(title, CONTENT_WIDTH) + 1;
+    put_text(grid, 1, title_x, title);
+
+    let header = format!("    Lesson #{}", app.lesson_number);
+    let counters = format!("✔: {}, ✘: {}    ", app.success_count, app.fail_count);
+    put_text(grid, header_row, 1, &header);
+    put_text(grid, header_row, FRAME_WIDTH - 1 - counters.chars().count(), &counters);
+
+    let (prompt, mismatch, left_pad) = prompt_strings(&app.lesson);
+    put_text(grid, prompt_row, 1 + left_pad, &prompt);
+    put_text(grid, mismatch_row, 1 + left_pad, &mismatch);
+
+    let wpm = format!(
+        "  need >= {:>3}WPM,   avg. {:>4}WPM,   last{:>4}WPM",
+        app.config.wpm_target,
+        app.avg_wpm(),
+        app.last_wpm
+    );
+    let acc = format!(
+        "  need >= {:>3}% Acc, avg. {:>4}% Acc, last{:>4}% Acc",
+        app.config.acc_target,
+        app.avg_acc(),
+        app.last_acc
+    );
+    put_text(grid, wpm_row, 1, &wpm);
+    put_text(grid, acc_row, 1, &acc);
+}
+
+fn draw_title_overlay(stdout: &mut Stdout) -> io::Result<()> {
+    let title = "ngrrram!";
+    let whole = "ngrrram!   by winterveil";
+    let x = (1 + centered_x(whole, CONTENT_WIDTH)) as u16;
+    queue!(
+        stdout,
+        MoveTo(x, 1),
+        SetAttribute(Attribute::Bold),
+        Print(title),
+        SetAttribute(Attribute::Reset)
+    )?;
+    Ok(())
+}
+
+fn draw_prompt_overlay(stdout: &mut Stdout, app: &App) -> io::Result<()> {
+    let height = if app.config.nokb { 13 } else { 19 };
+    let prompt_row = if height == 13 { 6 } else { 6 };
+    let (visible_display, _mismatch, left_pad) = prompt_strings(&app.lesson);
+    let visible_len = visible_display.chars().count();
+    if app.lesson.cursor >= visible_len {
+        return Ok(());
+    }
+
+    let bold_text: String = visible_display.chars().skip(app.lesson.cursor).collect();
+    let x = (1 + left_pad + app.lesson.cursor) as u16;
+    queue!(
+        stdout,
+        MoveTo(x, prompt_row as u16),
+        SetAttribute(Attribute::Bold),
+        Print(bold_text),
+        SetAttribute(Attribute::Reset)
+    )?;
+    Ok(())
+}
+
+fn prompt_strings(lesson: &LessonState) -> (String, String, usize) {
+    let display: Vec<char> = lesson
+        .expected
+        .iter()
+        .enumerate()
+        .map(|(idx, ch)| {
+            if idx < lesson.cursor && *ch == ' ' && lesson.space_mismatches[idx] {
+                '•'
+            } else {
+                *ch
+            }
+        })
+        .collect();
+
+    let mismatch: Vec<char> = lesson
+        .mismatches
+        .iter()
+        .map(|entry| entry.unwrap_or(' '))
+        .collect();
+
+    let display_str: String = display.into_iter().take(CONTENT_WIDTH).collect();
+    let mismatch_str: String = mismatch.into_iter().take(CONTENT_WIDTH).collect();
+    let width = UnicodeWidthStr::width(display_str.as_str());
+    let left_pad = if width < CONTENT_WIDTH {
+        (CONTENT_WIDTH - width) / 2
+    } else {
+        0
+    };
+    (display_str, mismatch_str, left_pad)
+}
+
+fn standard_keyboard_lines(layout: LayoutDef) -> [String; 7] {
+    let top_border = format!("┌{}┐", vec!["───"; 12].join("┬"));
+    let top_row = format!("│ {} │", layout.top.join(" │ "));
+    let top_join = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string();
+    let home_row = format!(" │ {} │", layout.home.join(" │ "));
+    let home_join = " └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string();
+    let bottom_row = format!("  │ {} │", layout.bottom.join(" │ "));
+    let bottom_border = "  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘".to_string();
+    [
+        top_border,
+        top_row,
+        top_join,
+        home_row,
+        home_join,
+        bottom_row,
+        bottom_border,
+    ]
+}
+
+fn ortholinear_keyboard_lines(layout: LayoutDef) -> [String; 7] {
+    let top_border = format!("┌{}┐", vec!["───"; 12].join("┬"));
+    let top_row = format!("│ {} │", layout.top.join(" │ "));
+    let divider = format!("├{}┤", vec!["───"; 12].join("┼"));
+    let home_row = format!("│ {} │ △ │", layout.home.join(" │ "));
+    let bottom_row = format!("│ {} │ △ │ △ │", layout.bottom.join(" │ "));
+    let bottom_border = format!("└{}┘", vec!["───"; 12].join("┴"));
+    [
+        top_border,
+        top_row,
+        divider.clone(),
+        home_row,
+        divider,
+        bottom_row,
+        bottom_border,
+    ]
+}
+
+fn centered_x(text: &str, width: usize) -> usize {
+    let text_width = UnicodeWidthStr::width(text);
+    if text_width >= width {
+        0
+    } else {
+        (width - text_width) / 2
+    }
+}
+
+fn put_text(grid: &mut [Vec<char>], row: usize, col: usize, text: &str) {
+    if row >= grid.len() {
+        return;
+    }
+    let mut x = col;
+    for ch in text.chars() {
+        if x >= FRAME_WIDTH {
+            break;
+        }
+        grid[row][x] = ch;
+        x += 1;
+    }
+}
