mod data;

use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process::{self, Command};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

use data::{LayoutDef, LayoutId, LessonKind, layout_def, ordered_pool, parse_layout};

const FRAME_WIDTH: usize = 79;
const CONTENT_WIDTH: usize = 77;

const HELP_TEXT: &str = "\
Usage: executable [OPTIONS]

Options:
  -n, --n <2|3|4|w|file>  use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file. [default: 2]
  -t, --top <1-200>       use the top X ngrams ordered by usage. [default: 50]
  -c, --combi <1-200>     how many different ngrams to use in a single lesson. [default: 2]
  -r, --rep <number>      how often to repeat *each* different ngram in a lesson. [default: 3]
  -w, --wpm <number>      the wpm threshold at which the lesson is considered a success. [default: 40]
  -a, --acc <0-100>       the accuracy in percent at which the lesson is considered a success. [default: 94]
      --emu-in <layout>   your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]
      --emu-out <layout>  the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]
      --show-ortho        show keyboard in ortholinear format
      --nokb              pass this flag to disable the keyboard layout display.
      --cat               the most important flag. don't practice alone.
  -h, --help              Print help
";

#[derive(Clone, Debug)]
struct Config {
    n: String,
    top: usize,
    combi: usize,
    rep: usize,
    wpm_target: u64,
    acc_target: u64,
    emu_in: String,
    emu_out: String,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            n: "2".to_string(),
            top: 50,
            combi: 2,
            rep: 3,
            wpm_target: 40,
            acc_target: 94,
            emu_in: String::new(),
            emu_out: String::new(),
            show_ortho: false,
            nokb: false,
            cat: false,
        }
    }
}

#[derive(Clone, Debug)]
enum PoolSource {
    Builtin(LessonKind),
    File(Vec<String>),
}

#[derive(Clone, Debug)]
struct LessonState {
    expected: Vec<char>,
    cursor: usize,
    mismatches: Vec<Option<char>>,
    space_mismatches: Vec<bool>,
    had_mistake: bool,
    locked: bool,
    started_at: Option<Instant>,
}

impl LessonState {
    fn new(text: String) -> Self {
        let expected: Vec<char> = text.chars().collect();
        let len = expected.len();
        Self {
            expected,
            cursor: 0,
            mismatches: vec![None; len],
            space_mismatches: vec![false; len],
            had_mistake: false,
            locked: false,
            started_at: None,
        }
    }
}

struct App {
    config: Config,
    pool: Vec<String>,
    emu: Option<(LayoutId, LayoutId)>,
    keyboard_layout: LayoutId,
    rng: SimpleRng,
    lesson_number: u64,
    success_count: u64,
    fail_count: u64,
    finished_lessons: u64,
    total_wpm: u64,
    total_acc: u64,
    last_wpm: u64,
    last_acc: u64,
    lesson: LessonState,
}

impl App {
    fn new(config: Config, source: PoolSource) -> Self {
        let emu = match (config.emu_in.is_empty(), config.emu_out.is_empty()) {
            (true, true) => None,
            (false, false) => Some((parse_layout(&config.emu_in), parse_layout(&config.emu_out))),
            _ => {
                eprintln!("You need to specify both emu_in and emu_out.");
                process::exit(1);
            }
        };

        let keyboard_layout = emu.map(|(_, out)| out).unwrap_or(LayoutId::Qwerty);
        let pool = match source {
            PoolSource::Builtin(kind) => ordered_pool(kind, config.top)
                .into_iter()
                .map(str::to_string)
                .collect(),
            PoolSource::File(words) => words,
        };

        let mut app = Self {
            config,
            pool,
            emu,
            keyboard_layout,
            rng: SimpleRng::seeded(),
            lesson_number: 1,
            success_count: 0,
            fail_count: 0,
            finished_lessons: 0,
            total_wpm: 0,
            total_acc: 0,
            last_wpm: 0,
            last_acc: 0,
            lesson: LessonState::new(String::new()),
        };
        app.start_next_lesson();
        app
    }

    fn start_next_lesson(&mut self) {
        if self.pool.is_empty() {
            panic_like_empty_pool();
        }

        let mut base = Vec::with_capacity(self.config.combi);
        for _ in 0..self.config.combi {
            let idx = self.rng.gen_range(self.pool.len());
            base.push(self.pool[idx].clone());
        }

        let mut lesson = String::new();
        for _ in 0..self.config.rep {
            for token in &base {
                lesson.push_str(token);
                lesson.push(' ');
            }
        }

        self.lesson = LessonState::new(lesson);
    }

    fn push_char(&mut self, ch: char) {
        if self.lesson.locked || self.lesson.cursor >= self.lesson.expected.len() {
            return;
        }

        if self.lesson.started_at.is_none() {
            self.lesson.started_at = Some(Instant::now());
        }

        let pos = self.lesson.cursor;
        let expected = self.lesson.expected[pos];
        let mapped = self.map_input_char(ch);

        if mapped != expected {
            self.lesson.had_mistake = true;
            if expected == ' ' {
                self.lesson.space_mismatches[pos] = true;
            }
            if mapped != ' ' {
                self.lesson.mismatches[pos] = Some(mapped);
            }
        }

        self.lesson.cursor += 1;
        if self.lesson.cursor == self.lesson.expected.len() {
            if self.lesson.had_mistake {
                self.lesson.locked = true;
            } else {
                self.finish_lesson();
            }
        }
    }

    fn map_input_char(&self, ch: char) -> char {
        let Some((input, output)) = self.emu else {
            return ch;
        };
        remap_char(ch, input, output)
    }

    fn finish_lesson(&mut self) {
        let non_space = self
            .lesson
            .expected
            .iter()
            .filter(|&&ch| ch != ' ')
            .count() as f64;

        let elapsed = self
            .lesson
            .started_at
            .map(|started| started.elapsed().as_secs_f64())
            .unwrap_or(0.0);

        let wpm = if non_space == 0.0 || elapsed <= 0.0 {
            0
        } else {
            (((non_space / 5.0) * 60.0) / elapsed).round() as u64
        };

        self.last_wpm = wpm;
        self.last_acc = 100;
        self.total_wpm += wpm;
        self.total_acc += 100;
        self.finished_lessons += 1;

        if wpm >= self.config.wpm_target && 100 >= self.config.acc_target {
            self.success_count += 1;
        } else {
            self.fail_count += 1;
        }

        self.lesson_number += 1;
        self.start_next_lesson();
    }

    fn avg_wpm(&self) -> u64 {
        if self.finished_lessons == 0 {
            0
        } else {
            self.total_wpm / self.finished_lessons
        }
    }

    fn avg_acc(&self) -> u64 {
        if self.finished_lessons == 0 {
            0
        } else {
            self.total_acc / self.finished_lessons
        }
    }
}

struct SimpleRng(u64);

impl SimpleRng {
    fn seeded() -> Self {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos() as u64;
        let mut seed = nanos ^ ((process::id() as u64) << 32) ^ 0x9E37_79B9_7F4A_7C15;
        if seed == 0 {
            seed = 0xA5A5_5A5A_DEAD_BEEF;
        }
        Self(seed)
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    fn gen_range(&mut self, upper: usize) -> usize {
        if upper <= 1 {
            0
        } else {
            (self.next_u64() % upper as u64) as usize
        }
    }
}

struct TerminalGuard {
    stty_state: String,
    active: bool,
}

impl TerminalGuard {
    fn enter() -> io::Result<Self> {
        let saved = Command::new("stty").arg("-g").output()?;
        let stty_state = String::from_utf8_lossy(&saved.stdout).trim().to_string();

        let status = Command::new("stty").args(["raw", "-echo"]).status()?;
        if !status.success() {
            return Err(io::Error::new(io::ErrorKind::Other, "failed to enable raw mode"));
        }

        let mut stdout = io::stdout();
        stdout.write_all(b"\x1b[?1049h\x1b[2J\x1b[H\x1b[?25h")?;
        stdout.flush()?;

        Ok(Self {
            stty_state,
            active: true,
        })
    }

    fn restore(&mut self) {
        if !self.active {
            return;
        }

        let _ = io::stdout().write_all(b"\x1b[0m\x1b[?1049l");
        let _ = io::stdout().flush();
        let _ = Command::new("stty").arg(&self.stty_state).status();
        self.active = false;
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        self.restore();
    }
}

fn main() {
    let config = parse_cli();
    let source = resolve_source(&config);
    if let Err(err) = run(config, source) {
        eprintln!("{err}");
        process::exit(1);
    }
}

fn parse_cli() -> Config {
    let mut config = Config::default();
    let args: Vec<String> = env::args().skip(1).collect();
    let mut i = 0usize;

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{HELP_TEXT}");
                process::exit(0);
            }
            "--show-ortho" => {
                config.show_ortho = true;
                i += 1;
            }
            "--nokb" => {
                config.nokb = true;
                i += 1;
            }
            "--cat" => {
                config.cat = true;
                i += 1;
            }
            "-n" | "--n" => {
                config.n = next_value(&args, &mut i, "--n <2|3|4|w|file>");
            }
            "-t" | "--top" => {
                config.top = parse_usize(
                    &next_value(&args, &mut i, "--top <1-200>"),
                    "--top <1-200>",
                );
            }
            "-c" | "--combi" => {
                config.combi = parse_usize(
                    &next_value(&args, &mut i, "--combi <1-200>"),
                    "--combi <1-200>",
                );
            }
            "-r" | "--rep" => {
                config.rep =
                    parse_usize(&next_value(&args, &mut i, "--rep <number>"), "--rep <number>");
            }
            "-w" | "--wpm" => {
                config.wpm_target =
                    parse_u64(&next_value(&args, &mut i, "--wpm <number>"), "--wpm <number>");
            }
            "-a" | "--acc" => {
                config.acc_target =
                    parse_u64(&next_value(&args, &mut i, "--acc <0-100>"), "--acc <0-100>");
            }
            "--emu-in" => {
                config.emu_in = next_value(&args, &mut i, "--emu-in <layout>");
            }
            "--emu-out" => {
                config.emu_out = next_value(&args, &mut i, "--emu-out <layout>");
            }
            _ if arg.starts_with("--n=") => {
                config.n = arg[4..].to_string();
                i += 1;
            }
            _ if arg.starts_with("--top=") => {
                config.top = parse_usize(&arg[6..], "--top <1-200>");
                i += 1;
            }
            _ if arg.starts_with("--combi=") => {
                config.combi = parse_usize(&arg[8..], "--combi <1-200>");
                i += 1;
            }
            _ if arg.starts_with("--rep=") => {
                config.rep = parse_usize(&arg[6..], "--rep <number>");
                i += 1;
            }
            _ if arg.starts_with("--wpm=") => {
                config.wpm_target = parse_u64(&arg[6..], "--wpm <number>");
                i += 1;
            }
            _ if arg.starts_with("--acc=") => {
                config.acc_target = parse_u64(&arg[6..], "--acc <0-100>");
                i += 1;
            }
            _ if arg.starts_with("--emu-in=") => {
                config.emu_in = arg[9..].to_string();
                i += 1;
            }
            _ if arg.starts_with("--emu-out=") => {
                config.emu_out = arg[10..].to_string();
                i += 1;
            }
            _ => unexpected_argument(arg),
        }
    }

    validate_range("top", config.top as u64, 1, 200);
    validate_range("combi", config.combi as u64, 1, 200);
    validate_range("rep", config.rep as u64, 1, 200);
    validate_range("wpm", config.wpm_target, 1, 200);
    validate_range("acc", config.acc_target, 0, 100);

    config
}

fn next_value(args: &[String], index: &mut usize, spec: &str) -> String {
    if *index + 1 >= args.len() {
        missing_value(spec);
    }
    let value = args[*index + 1].clone();
    *index += 2;
    value
}

fn parse_usize(raw: &str, spec: &str) -> usize {
    match raw.parse::<usize>() {
        Ok(value) => value,
        Err(err) => invalid_value(raw, spec, &err.to_string()),
    }
}

fn parse_u64(raw: &str, spec: &str) -> u64 {
    match raw.parse::<u64>() {
        Ok(value) => value,
        Err(err) => invalid_value(raw, spec, &err.to_string()),
    }
}

fn invalid_value(raw: &str, spec: &str, err: &str) -> ! {
    eprintln!("error: invalid value '{raw}' for '{spec}': {err}");
    eprintln!();
    eprintln!("For more information, try '--help'.");
    process::exit(2);
}

fn unexpected_argument(arg: &str) -> ! {
    eprintln!("error: unexpected argument '{arg}' found");
    eprintln!();
    eprintln!("Usage: executable [OPTIONS]");
    eprintln!();
    eprintln!("For more information, try '--help'.");
    process::exit(2);
}

fn missing_value(spec: &str) -> ! {
    eprintln!("error: a value is required for '{spec}' but none was supplied");
    eprintln!();
    eprintln!("Usage: executable [OPTIONS]");
    eprintln!();
    eprintln!("For more information, try '--help'.");
    process::exit(2);
}

fn validate_range(name: &str, value: u64, min: u64, max: u64) {
    if value < min || value > max {
        eprintln!("Invalid argument for {name}. Use a number between {min} and {max}.");
        process::exit(1);
    }
}

fn resolve_source(config: &Config) -> PoolSource {
    match config.n.as_str() {
        "2" => PoolSource::Builtin(LessonKind::Bigrams),
        "3" => PoolSource::Builtin(LessonKind::Trigrams),
        "4" => PoolSource::Builtin(LessonKind::Tetragrams),
        "w" => PoolSource::Builtin(LessonKind::Words),
        path => {
            let raw = match fs::read_to_string(path) {
                Ok(text) => text,
                Err(_) => {
                    eprintln!("File not found: {path}");
                    process::exit(1);
                }
            };
            let words = raw
                .split(',')
                .filter(|part| !part.is_empty())
                .map(|part| part.to_string())
                .collect::<Vec<_>>();
            PoolSource::File(words)
        }
    }
}

fn run(config: Config, source: PoolSource) -> io::Result<()> {
    let mut guard = TerminalGuard::enter()?;
    let mut app = App::new(config, source);
    render(&app)?;

    let stdin = io::stdin();
    let mut stdin = stdin.lock();

    loop {
        let ch = read_char(&mut stdin)?;
        if ch == '\u{1b}' {
            break;
        }
        app.push_char(ch);
        render(&app)?;
    }

    guard.restore();
    Ok(())
}

fn read_char<R: Read>(reader: &mut R) -> io::Result<char> {
    let mut first = [0u8; 1];
    reader.read_exact(&mut first)?;
    if first[0] < 0x80 {
        return Ok(first[0] as char);
    }

    let width = match first[0] {
        0xC0..=0xDF => 2,
        0xE0..=0xEF => 3,
        0xF0..=0xF7 => 4,
        _ => 1,
    };

    let mut bytes = vec![first[0]];
    if width > 1 {
        let mut rest = vec![0u8; width - 1];
        reader.read_exact(&mut rest)?;
        bytes.extend(rest);
    }

    let decoded = std::str::from_utf8(&bytes)
        .ok()
        .and_then(|s| s.chars().next())
        .unwrap_or('\u{fffd}');
    Ok(decoded)
}

fn panic_like_empty_pool() -> ! {
    eprintln!();
    eprintln!(
        "thread 'main' ({}) panicked at src/game.rs:18:45:",
        process::id()
    );
    eprintln!("called `Option::unwrap()` on a `None` value");
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    process::exit(101);
}

fn remap_char(ch: char, input: LayoutId, output: LayoutId) -> char {
    if ch == ' ' {
        return ' ';
    }

    if let Some(mapped) = remap_exact(ch, input, output) {
        return mapped;
    }

    if ch.is_ascii_uppercase() {
        let lower = ch.to_ascii_lowercase();
        if let Some(mapped) = remap_exact(lower, input, output) {
            return mapped.to_ascii_uppercase();
        }
    }

    ch
}

fn remap_exact(ch: char, input: LayoutId, output: LayoutId) -> Option<char> {
    let input_layout = layout_def(input);
    let output_layout = layout_def(output);

    for (in_row, out_row) in [
        (&input_layout.top[..], &output_layout.top[..]),
        (&input_layout.home[..], &output_layout.home[..]),
        (&input_layout.bottom[..], &output_layout.bottom[..]),
    ] {
        for (from, to) in in_row.iter().zip(out_row.iter()) {
            if from.chars().next() == Some(ch) {
                return to.chars().next();
            }
        }
    }

    None
}

fn render(app: &App) -> io::Result<()> {
    let height = if app.config.nokb { 13 } else { 19 };
    let mut grid = vec![vec![' '; FRAME_WIDTH]; height];

    draw_top_border(&mut grid);
    if app.config.nokb {
        draw_nokb_body(&mut grid, app);
    } else {
        draw_keyboard_body(&mut grid, app);
    }

    let prompt_row = 6usize;
    let title_row = 1usize;
    let mut stdout = io::stdout();
    let mut out = String::from("\x1b[2J\x1b[H");

    for (idx, row) in grid.iter().enumerate() {
        if idx == title_row {
            out.push_str(&styled_title_line());
        } else if idx == prompt_row {
            out.push_str(&styled_prompt_line(app));
        } else {
            out.extend(row.iter());
        }
        if idx + 1 < grid.len() {
            out.push('\n');
        }
    }
    out.push_str("\x1b[0m");

    stdout.write_all(out.as_bytes())?;
    stdout.flush()
}

fn draw_top_border(grid: &mut [Vec<char>]) {
    put_text(grid, 0, 0, "╭");
    put_text(grid, 0, FRAME_WIDTH - 1, "╮");
    for x in 1..(FRAME_WIDTH - 1) {
        put_text(grid, 0, x, "─");
    }
    put_text(grid, 0, 66, " Quit <esc> ");
}

fn draw_nokb_body(grid: &mut [Vec<char>], app: &App) {
    draw_framed_content(grid, 1, 12);
    put_divider(grid, 2);
    put_divider(grid, 4);
    put_divider(grid, 9);
    draw_bottom_border(grid, 12);
    draw_shared_content(grid, app, 3, 7, 10, 11);

    if app.config.cat {
        put_text(grid, 10, 63, "/\\_/\\\\");
        put_text(grid, 11, 62, ">(•༝• )<");
        put_text(grid, 12, 1, "────────────────────────────────────────────────────────────    |    \\───────");
    }
}

fn draw_keyboard_body(grid: &mut [Vec<char>], app: &App) {
    draw_framed_content(grid, 1, 18);
    put_divider(grid, 2);
    put_divider(grid, 4);
    put_divider(grid, 15);
    draw_bottom_border(grid, 18);
    draw_shared_content(grid, app, 3, 7, 16, 17);

    let layout = layout_def(app.keyboard_layout);
    let lines = if app.config.show_ortho {
        ortholinear_keyboard_lines(layout)
    } else {
        standard_keyboard_lines(layout)
    };
    let x = if app.config.cat {
        5
    } else {
        centered_x(&lines[0], CONTENT_WIDTH) + 1
    };

    for (idx, line) in lines.iter().enumerate() {
        put_text(grid, 8 + idx, x, line);
    }

    if app.config.cat {
        put_text(grid, 10, 65, "/\\_/\\\\");
        put_text(grid, 11, 63, ">(•༝• )<");
        put_text(grid, 12, 64, "|    \\");
        put_text(grid, 13, 64, "|| |  )");
        put_text(grid, 14, 64, "ll-l-//");
        put_text(grid, 15, 1, "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───");
        put_text(grid, 16, 69, "\\\\");
        put_text(grid, 17, 69, "V");
    }
}

fn draw_framed_content(grid: &mut [Vec<char>], start: usize, end: usize) {
    for row in start..end {
        put_text(grid, row, 0, "│");
        put_text(grid, row, FRAME_WIDTH - 1, "│");
    }
}

fn put_divider(grid: &mut [Vec<char>], row: usize) {
    put_text(grid, row, 0, "│");
    put_text(grid, row, FRAME_WIDTH - 1, "│");
    for x in 1..(FRAME_WIDTH - 1) {
        put_text(grid, row, x, "─");
    }
}

fn draw_bottom_border(grid: &mut [Vec<char>], row: usize) {
    put_text(grid, row, 0, "╰");
    put_text(grid, row, FRAME_WIDTH - 1, "╯");
    for x in 1..(FRAME_WIDTH - 1) {
        put_text(grid, row, x, "─");
    }
}

fn draw_shared_content(
    grid: &mut [Vec<char>],
    app: &App,
    header_row: usize,
    mismatch_row: usize,
    wpm_row: usize,
    acc_row: usize,
) {
    let title = "ngrrram!   by winterveil";
    let title_x = centered_x(title, CONTENT_WIDTH) + 1;
    put_text(grid, 1, title_x, title);

    let header = format!("    Lesson #{}", app.lesson_number);
    let counters = format!("✔: {}, ✘: {}    ", app.success_count, app.fail_count);
    put_text(grid, header_row, 1, &header);
    put_text(grid, header_row, FRAME_WIDTH - 1 - counters.chars().count(), &counters);

    let (_prompt, mismatch, left_pad) = prompt_strings(&app.lesson);
    put_text(grid, mismatch_row, 1 + left_pad, &mismatch);

    let wpm = format!(
        "  need >= {:>3}WPM,   avg. {:>4}WPM,   last{:>4}WPM",
        app.config.wpm_target,
        app.avg_wpm(),
        app.last_wpm
    );
    let acc = format!(
        "  need >= {:>3}% Acc, avg. {:>4}% Acc, last{:>4}% Acc",
        app.config.acc_target,
        app.avg_acc(),
        app.last_acc
    );
    put_text(grid, wpm_row, 1, &wpm);
    put_text(grid, acc_row, 1, &acc);
}

fn styled_title_line() -> String {
    let title = "ngrrram!   by winterveil";
    let title_x = centered_x(title, CONTENT_WIDTH);
    let mut inside = String::new();
    inside.push_str(&" ".repeat(title_x));
    inside.push_str("\x1b[1mngrrram!\x1b[0m   by winterveil");
    let plain_width = title.chars().count();
    inside.push_str(&" ".repeat(CONTENT_WIDTH - title_x - plain_width));
    format!("│{}│", inside)
}

fn styled_prompt_line(app: &App) -> String {
    let (prompt, _mismatch, left_pad) = prompt_strings(&app.lesson);
    let visible_len = prompt.chars().count();
    let cursor = app.lesson.cursor.min(visible_len);
    let typed: String = prompt.chars().take(cursor).collect();
    let remaining: String = prompt.chars().skip(cursor).collect();

    let mut inside = String::new();
    inside.push_str(&" ".repeat(left_pad));
    inside.push_str(&typed);
    if !remaining.is_empty() {
        inside.push_str("\x1b[1m");
        inside.push_str(&remaining);
        inside.push_str("\x1b[0m");
    }
    inside.push_str(&" ".repeat(CONTENT_WIDTH - left_pad - visible_len));
    format!("│{}│", inside)
}

fn prompt_strings(lesson: &LessonState) -> (String, String, usize) {
    let display: String = lesson
        .expected
        .iter()
        .enumerate()
        .map(|(idx, ch)| {
            if idx < lesson.cursor && *ch == ' ' && lesson.space_mismatches[idx] {
                '•'
            } else {
                *ch
            }
        })
        .take(CONTENT_WIDTH)
        .collect();

    let mismatch: String = lesson
        .mismatches
        .iter()
        .map(|entry| entry.unwrap_or(' '))
        .take(CONTENT_WIDTH)
        .collect();

    let width = display.chars().count();
    let left_pad = if width < CONTENT_WIDTH {
        (CONTENT_WIDTH - width) / 2
    } else {
        0
    };
    (display, mismatch, left_pad)
}

fn standard_keyboard_lines(layout: LayoutDef) -> [String; 7] {
    let top_border = format!("┌{}┐", vec!["───"; 12].join("┬"));
    let top_row = format!("│ {} │", layout.top.join(" │ "));
    let top_join = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string();
    let home_row = format!(" │ {} │", layout.home.join(" │ "));
    let home_join = " └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string();
    let bottom_row = format!("  │ {} │", layout.bottom.join(" │ "));
    let bottom_border = "  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘".to_string();
    [
        top_border,
        top_row,
        top_join,
        home_row,
        home_join,
        bottom_row,
        bottom_border,
    ]
}

fn ortholinear_keyboard_lines(layout: LayoutDef) -> [String; 7] {
    let top_border = format!("┌{}┐", vec!["───"; 12].join("┬"));
    let top_row = format!("│ {} │", layout.top.join(" │ "));
    let divider = format!("├{}┤", vec!["───"; 12].join("┼"));
    let home_row = format!("│ {} │ △ │", layout.home.join(" │ "));
    let bottom_row = format!("│ {} │ △ │ △ │", layout.bottom.join(" │ "));
    let bottom_border = format!("└{}┘", vec!["───"; 12].join("┴"));
    [
        top_border,
        top_row,
        divider.clone(),
        home_row,
        divider,
        bottom_row,
        bottom_border,
    ]
}

fn centered_x(text: &str, width: usize) -> usize {
    let text_width = text.chars().count();
    if text_width >= width {
        0
    } else {
        (width - text_width) / 2
    }
}

fn put_text(grid: &mut [Vec<char>], row: usize, col: usize, text: &str) {
    if row >= grid.len() {
        return;
    }
    let mut x = col;
    for ch in text.chars() {
        if x >= FRAME_WIDTH {
            break;
        }
        grid[row][x] = ch;
        x += 1;
    }
}

